import{z as t,x as p,o as n,c as o,q as l,j as F,D as E,d as r,s as i,S as B,b as e}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"混合精度 BF16 / FP8 训练","description":"","frontmatter":{"title":"混合精度 BF16 / FP8 训练","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/pretrain-mixed-precision.md","filePath":"llm/pretrain-mixed-precision.md","lastUpdated":1791413859000}'),A={name:"llm/pretrain-mixed-precision.md"};function P(m,a,d,f,h,x){const s=p("Mermaid");return n(),o("div",null,[a[2]||(a[2]=l('<h1 id="混合精度-bf16-fp8-训练" tabindex="-1">混合精度 BF16 / FP8 训练 <a class="header-anchor" href="#混合精度-bf16-fp8-训练" aria-label="Permalink to &quot;混合精度 BF16 / FP8 训练&quot;">​</a></h1><div class="epigraph"><p>用更窄的尾数做矩阵乘，用足够的指数位保住梯度不消失；主权重仍在较宽的格式里累积。</p><footer>—— Micikevicius 等，混合精度训练；NVIDIA Transformer Engine 的 FP8 路径</footer></div><p><a href="/llm/grad-clip-loss-spike">上一课</a>用全局范数裁剪保方向、把幅度钉进半径 \\(c\\) 的球；尖峰仍有精度这一类来源。缺口是格式宽度。预训练的墙几乎总是 GEMM：窄格式涨吞吐、降显存，同时让小梯度下溢、大激活溢出。本课按 FP16 → BF16 → FP8 写同一套分工：计算用窄格式，主权重与 softmax、损失用宽格式。不重讲 \\(c\\) 的 All-Reduce。后课 μP 与衰减默认已经读完：训练 FP8 的目标是跟上 BF16 更新，不是完成部署量化。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>FP32 的指数 8 位、尾数 23 位，对反向传播里跨层相乘的梯度来说过于奢侈，也对 Tensor Core 不友好。FP16 把指数收到 5 位，动态范围大约 \\(6\\times 10^{-8}\\) 到 \\(6\\times 10^{4}\\)。许多合法梯度的幅度落在下限以下，反传结束时变成全零，权重不再更新——这是损失缩放要救的对象。上限附近，注意力分数与未归一的 logits 容易 Inf。于是出现一对矛盾：既要把梯度乘大以免下溢，又不能把激活乘大以免溢出。</p><p>BF16（brain floating point）把指数恢复到与 FP32 相同的 8 位，尾数只留 7 位。动态范围不再是瓶颈，缺的是精度：累加与小更新会有量化噪声。FP8 更极端：常见两种布局 E4M3（指数 4、尾数 3，偏向前向）与 E5M2（指数 5、尾数 2，偏向梯度）。没有额外缩放，绝大多数张量根本塞不进 FP8。混合精度训练要回答的不是「用哪种字面格式」，而是「缩放放在哪、主权重用什么、哪些算子不准降」。</p><p><span class="marginnote">术语翻译：「指数位」决定一个数最大能多大、最小能多小（动态范围）；「尾数位」决定相邻两个可表示的数挨得多近（精度）。FP16 像一把量程窄、刻度密的尺子；BF16 量程和 FP32 一样宽，只是刻度稀——大数不丢，小变化分不清。</span></p><h3 id="fp16-为什么要损失缩放" tabindex="-1">FP16 为什么要损失缩放 <a class="header-anchor" href="#fp16-为什么要损失缩放" aria-label="Permalink to &quot;FP16 为什么要损失缩放&quot;">​</a></h3><p>损失缩放把目标乘一个因子 \\(s\\)（例如 \\(2^{10}\\) 到 \\(2^{16}\\)），反传链路上的梯度整体乘 \\(s\\)，使小梯度进入 FP16 可表示区；更新前再除以 \\(s\\)。动态损失缩放观察是否出现 Inf/NaN：连续若干步干净则尝试增大 \\(s\\)，一溢出就丢掉该步并减小 \\(s\\)。主权重以 FP32 保存，FP16 只用于前向、反传和通信。没有 FP32 主权重，FP16 的更新量化误差会把小学习率下的步长吞掉。</p><p><span class="marginnote">数字实例：FP16 最小正规数约 \\(6\\times 10^{-5}\\)。一个幅度 \\(10^{-6}\\) 的梯度，直接反传必然下溢成零、权重不再更新；乘上 \\(s=2^{10}=1024\\) 后约 \\(10^{-3}\\)，稳稳进入可表示区，等优化器用完再除回去。缩放不改任何数学含义，只是把数搬进「尺子量得到的范围」。</span></p><p><span class="marginnote">损失缩放不是改损失函数的定义。评测、日志里的损失应是未乘 \\(s\\) 的值。优化器看到的梯度必须在进入 Adam 之前 unscale，否则二阶矩 \\(v\\) 会按 \\(s^2\\) 膨胀，学习率含义全乱。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>当代预训练默认 BF16：前向与梯度用 BF16，主权重与 Adam 状态用 FP32（或不存单独主权重、在 BF16 权重上用 FP32 动量——这是实现分歧，数值上后者更糙）。BF16 的指数与 FP32 同宽，动态损失缩放通常关闭。仍建议把 softmax、损失、部分归约留在 FP32，因为尾数短，指数和的消除误差大。</p><p>FP8 训练（Transformer Engine 思路）在 BF16 配方上再插一层张量级缩放。每个参与 GEMM 的张量配一个缩放因子 \\(\\alpha\\)，存储的是 \\(x_{\\mathrm{fp8}}\\approx x/(\\alpha)\\) 或硬件约定的倒数形式，使 \\(x\\) 的最大绝对值（amax）映射到 E4M3/E5M2 的最大有限值附近。前向常用 E4M3（尾数多一点），梯度常用 E5M2（范围大一点）。这不是唯一拆法，但是 NVIDIA 文档与 TE 的典型路径。</p><p>延迟缩放（delayed scaling）：本步用历史若干步的 amax 统计来选 \\(\\alpha\\)，本步的 amax 写入历史，供后续步使用。避免为了当前 amax 先做一次额外的全张量扫描再量化。amax 窗口过大，缩放跟不上突然的激活暴涨，溢出；过小，统计噪声让 \\(\\alpha\\) 抖动，等效额外的学习率噪声。出现溢出时，实现通常跳过该步或回退到较宽格式——与动态损失缩放是同一类控制回路，只是对象从「全局 \\(s\\)」变成「每张量 \\(\\alpha\\)」。</p>',15)),(n(),F(B,null,{default:E(()=>[i(s,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22FP32%20%E4%B8%BB%E6%9D%83%E9%87%8D%22%5D%20--%3E%20C%5B%22%E9%87%8F%E5%8C%96%20%2F%20%E7%B1%BB%E5%9E%8B%E8%BD%AC%E6%8D%A2%22%5D%0A%20%20C%20--%3E%20G%5B%22GEMM%3A%20BF16%20%E6%88%96%20FP8%22%5D%0A%20%20G%20--%3E%20H%5B%22Softmax%20%2F%20LN%20%2F%20%E6%8D%9F%E5%A4%B1%3A%20%E6%9B%B4%E9%AB%98%E7%B2%BE%E5%BA%A6%22%5D%0A%20%20H%20--%3E%20B%5B%22%E5%8F%8D%E4%BC%A0%20GEMM%22%5D%0A%20%20B%20--%3E%20U%5B%22Unscale%20%E5%90%8E%E6%9B%B4%E6%96%B0%E4%B8%BB%E6%9D%83%E9%87%8D%22%5D%0A%20%20S%5B%22%E6%8D%9F%E5%A4%B1%E7%BC%A9%E6%94%BE%E6%88%96%20FP8%20amax%22%5D%20--%3E%20B%0A%20%20S%20--%3E%20U%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h3",{id:"fp8-与-transformer-engine-的缩放",tabindex:"-1"},[r("FP8 与 Transformer Engine 的缩放 "),e("a",{class:"header-anchor",href:"#fp8-与-transformer-engine-的缩放","aria-label":'Permalink to "FP8 与 Transformer Engine 的缩放"'},"​")],-1)),a[4]||(a[4]=e("p",null,"TE 把线性层的输入、权重、梯度分别量化。权重可以每步从 FP32/BF16 主副本转 FP8，也可以维护一份 FP8 权重再定期刷新。矩阵乘在 Tensor Core 上以 FP8 输入、较高精度累加（通常 FP32 累加器）。缩放因子要进入这次乘的元数据，使数值等于 \\(\\alpha_x\\alpha_w\\) 意义下的真值。漏乘一个 \\(\\alpha\\)，相当于给该层乘了一个随机的学习率。流水线与张量并行下，amax 的归约必须跨参与该张量的设备，否则每张卡各用各的范围，分片拼接后尺度不一致。",-1)),a[5]||(a[5]=e("p",null,"全局损失缩放在 FP8 里仍然可能出现：梯度的 E5M2 再窄，光靠 per-tensor \\(\\alpha\\) 不够时，用 \\(s\\) 把损失抬一层。两条缩放叠在一起时，unscale 的顺序必须与正向乘 \\(s\\)、量化除 \\(\\alpha\\) 互逆。这是实现里最容易静默出错的地方：训练能跑、损失看起来在降，但有效学习率已经不是配置文件里的数。",-1)),a[6]||(a[6]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[7]||(a[7]=e("p",null,"窄格式伤害两类运算不同。GEMM 是乘加，Tensor Core 的累加器比输入宽，个别乘的尾数误差被大量项平均，预训练对这种噪声相对耐。逐元素的归一化、softmax、交叉熵，是先减最大值再指数再除，对动态范围和尾数都敏感：最大值一溢出，整行 NaN；尾数不够，小概率 token 的梯度消失。所以混合精度的边界画在「矩阵乘可以窄、归约与归一化要宽」。",-1)),(n(),F(B,null,{default:E(()=>[i(s,{id:"mermaid-59",class:"mermaid",graph:"flowchart%20TD%0A%20%20OP%5B%22%E4%B8%80%E4%B8%AA%E7%AE%97%E5%AD%90%E8%AF%A5%E7%94%A8%E4%BB%80%E4%B9%88%E7%B2%BE%E5%BA%A6%3F%22%5D%20--%3E%20G%7B%22%E6%98%AF%E5%A4%A7%E5%9E%8B%E7%9F%A9%E9%98%B5%E4%B9%98%20GEMM%3F%22%7D%0A%20%20G%20--%3E%7C%22%E6%98%AF%22%7C%20NAR%5B%22%E7%AA%84%E6%A0%BC%E5%BC%8F%E8%BE%93%E5%85%A5%3A%20BF16%20%E6%88%96%20FP8%2C%20FP32%20%E7%B4%AF%E5%8A%A0%22%5D%0A%20%20G%20--%3E%7C%22%E5%90%A6%22%7C%20E%7B%22%E5%BD%92%E4%B8%80%E5%8C%96%20%2F%20softmax%20%2F%20%E6%8D%9F%E5%A4%B1%3F%22%7D%0A%20%20E%20--%3E%7C%22%E6%98%AF%22%7C%20WIDE%5B%22%E5%BF%85%E9%A1%BB%20FP32%3A%20%E5%85%88%E5%87%8F%E6%9C%80%E5%A4%A7%E5%80%BC%E5%86%8D%E6%8C%87%E6%95%B0%22%5D%0A%20%20E%20--%3E%7C%22%E5%90%A6%22%7C%20MID%5B%22%E6%8C%89%E5%B8%A6%E5%AE%BD%E4%B8%8E%E6%98%BE%E5%AD%98%E6%9D%83%E8%A1%A1%2C%20%E9%80%9A%E4%BF%A1%E5%B8%B8%E7%94%A8%20BF16%22%5D%0A%20%20WIDE%20--%3E%20W%5B%22%E6%9C%80%E5%A4%A7%E5%80%BC%E4%B8%80%E6%BA%A2%E5%87%BA%2C%20%E6%95%B4%E8%A1%8C%E5%8F%98%20NaN%22%5D%0A%20%20NAR%20--%3E%20N%5B%22%E4%B8%AA%E5%88%AB%E5%B0%BE%E6%95%B0%E8%AF%AF%E5%B7%AE%E8%A2%AB%E5%A4%A7%E9%87%8F%E4%B9%98%E5%8A%A0%E5%B9%B3%E5%9D%87%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=l('<p>BF16 相对 FP16 的本质是把预算从尾数挪到指数。梯度下溢减少，更新噪声增加。大 batch、大模型上噪声被平均，BF16 成为默认；极小模型或对数值极敏感的对比学习，有时仍能测到与 FP32 的差。FP8 把这条路再走一步：必须靠 \\(\\alpha\\) 把张量搬进窄格子。\\(\\alpha\\) 若按张量全局取 amax，一张量里大多数值挤在量化格子的少数档，等于有效位数更少；分块（block / mx）缩放把局部范围分开，精度更好，元数据与内核更复杂。OCP 的微缩放格式属于后一方向，本篇不展开标准文本。</p><p><span class="marginnote">「BF16 不需要损失缩放」是经验默认，不是证明。若某层梯度系统性小于 BF16 的最小正规数，它们照样变零。遇到「某些层完全不更新」时，先看梯度直方图，而不是先开 FP8。</span></p><h3 id="哪些算子必须留在高精度" tabindex="-1">哪些算子必须留在高精度 <a class="header-anchor" href="#哪些算子必须留在高精度" aria-label="Permalink to &quot;哪些算子必须留在高精度&quot;">​</a></h3><p>最低限度：损失、softmax（注意力与词预测）、LayerNorm / RMSNorm 的统计量。嵌入查找可以用 BF16 存、FP32 累加梯度。梯度裁剪的范数应在 unscale 之后、在约定的宽格式里算。检查点存主权重的宽副本；只存 FP8 权重无法无损恢复训练。</p><p>通信精度是另一处权衡。All-Reduce BF16 梯度省带宽，但多次累加的误差大于 FP32。ZeRO 的 Reduce-Scatter 同理。FP8 通信需要各 rank 对同一缩放约定，否则求和无定义。多数系统仍用 BF16 通信梯度，只把本地 GEMM 降到 FP8。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把训练 FP8 和推理 INT8/FP8 当成同一套缩放。推理可以离线校准、可以权重量化感知训练；预训练的 FP8 每步都在变 amax，目标是匹配 BF16 的更新轨迹，而不是压缩部署体积。用推理量化的校准集去「验证」预训练 FP8，问错了问题。</p><p>动态范围突发（损失尖峰、数据尖峰）会让延迟缩放滞后一拍：\\(\\alpha\\) 仍按旧 amax，新激活溢出。这是 FP8 训练与尖峰互相放大的通道。应对是溢出则跳过该步、缩小 \\(\\alpha\\)、或该层回退 BF16。把 clip 阈值收得很紧可以减少溢出，也会扭曲有效学习率。</p><p><span class="marginnote">常见误区：初学者容易以为「混合精度」就是把配置里的 dtype 全改成 bf16 一劳永逸。它其实是一张分工表——GEMM 窄、主权重与归约宽、缩放因子单独维护；真的全局换窄格式，往往第一步 softmax 就整行 NaN，而且报错位置离真正原因很远。</span></p><p><span class="marginnote">主权重的格式决定「小学习率是否还能积累」。只把 GEMM 换成 FP8、却用 BF16 存权重又关掉 FP32 主副本，小更新会被量化台阶挡住，表现为损失早停在一个平台。省显存之前先确认优化器状态仍在 FP32。</span></p><p>硬件绑定：没有 FP8 Tensor Core 的设备上模拟 FP8 没有吞吐意义。BF16 在 Ampere 及以后、以及 TPU 上是一等公民。同一配方在只支持 FP16 的卡上必须重开损失缩放，不能只改 dtype 名字。可复现实验应写明：计算 dtype、通信 dtype、主权重 dtype、是否动态损失缩放、FP8 的 E4M3/E5M2 分配与 amax 窗口。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>混合精度用窄格式做 GEMM，用宽格式存主权重与做 softmax、归一化、损失。</li><li>FP16 依赖损失缩放把梯度抬进可表示范围；BF16 指数与 FP32 同宽，默认不再用全局 \\(s\\)。</li><li>FP8 需要 per-tensor（或分块）缩放与 amax 统计；Transformer Engine 典型前向 E4M3、梯度 E5M2，并可与损失缩放叠用。</li><li>Unscale 顺序、amax 的跨设备归约、通信精度，都会静默改写有效学习率。</li><li>训练 FP8 的目标是跟上 BF16 更新，不是完成部署量化。</li><li>出处：Micikevicius 等，混合精度训练，2018；BF16 作为硬件格式的工程实践；NVIDIA Transformer Engine 文档中的 FP8 配方与延迟缩放。</li></ul>',13))])}const M=t(A,[["render",P]]);export{D as __pageData,M as default};
